"""Banque pedagogique React - codes valides par le prof.
Ajouter un snippet = 1 entree :  "cle": ("Titre affiche", "code...").
La cle sert a la recherche (ex: 'usereducer' trouve par 'donne le code usereducer')."""
EXEMPLES = {
    "jsx": ("JSX de base",
             "function Bonjour(){\n  const nom = 'React';\n  return <h1>Bonjour {nom} !</h1>;\n}"),
    "composant": ("Composant + modification",
                  "function Carte({nom}){\n  return <div>{nom}</div>;\n}\nfunction App(){\n  return <Carte nom=\"React\" />;\n}"),
    "props": ("Props parent->enfant",
              "function Bouton({titre}){\n  return <button>{titre}</button>;\n}\nfunction App(){\n  return <Bouton titre=\"Valider\" />;\n}"),
    "children": ("Props children",
                 "function Cadre({children}){\n  return <div className=\"cadre\">{children}</div>;\n}\nfunction App(){\n  return <Cadre><p>Dedans</p></Cadre>;\n}"),
    "usestate": ("Compteur useState (states)",
                 "import { useState } from 'react';\nfunction Compteur(){\n  const [count, setCount] = useState(0);\n  return <button onClick={()=>setCount(count+1)}>Clics : {count}</button>;\n}"),
    "formulaire": ("Formulaire controle (states)",
                   "import { useState } from 'react';\nfunction Form(){\n  const [nom, setNom] = useState('');\n  return (<form onSubmit={e=>e.preventDefault()}>\n    <input value={nom} onChange={e=>setNom(e.target.value)} placeholder=\"Nom\" />\n    <p>{nom}</p>\n  </form>);\n}"),
    "conditionnel": ("Rendu conditionnel",
                     "function Salut({connecte}){\n  if(!connecte) return <p>Connectez-vous</p>;\n  return <p>Bienvenue !</p>;\n}"),
    "listes": ("Listes + keys",
               "function Liste({items}){\n  return <ul>{items.map(it=><li key={it.id}>{it.nom}</li>)}</ul>;\n}"),
    "evenements": ("Evenements",
                   "function Clic(){\n  const dire = ()=>alert('Clic !');\n  return <button onClick={dire}>Clique</button>;\n}"),
    "usereffect": ("useEffect (hook effet)",
                   "import { useState, useEffect } from 'react';\nfunction Titre({count}){\n  useEffect(()=>{ document.title = `Clics : ${count}`; }, [count]);\n  return <p>{count}</p>;\n}"),
    "cleanup": ("useEffect cleanup",
                "import { useEffect } from 'react';\nfunction Horloge(){\n  useEffect(()=>{\n    const id = setInterval(()=>console.log('tic'), 1000);\n    return ()=>clearInterval(id);\n  }, []);\n  return <p>Horloge</p>;\n}"),
    "useref": ("useRef (DOM)",
               "import { useRef } from 'react';\nfunction Focus(){\n  const ref = useRef(null);\n  return (<div><input ref={ref} /><button onClick={()=>ref.current.focus()}>Focus</button></div>);\n}"),
    "usememo": ("useMemo (perf)",
                "import { useMemo, useState } from 'react';\nfunction Gros({nombres}){\n  const [f, setF] = useState('');\n  const total = useMemo(()=>nombres.reduce((a,b)=>a+b,0), [nombres]);\n  return <p>{total} <input value={f} onChange={e=>setF(e.target.value)} /></p>;\n}"),
    "usecallback": ("useCallback (perf)",
                    "import { useState, useCallback } from 'react';\nfunction App(){\n  const [n, setN] = useState(0);\n  const inc = useCallback(()=>setN(v=>v+1), []);\n  return <button onClick={inc}>{n}</button>;\n}"),
    "usecontext": ("useContext (partage)",
                   "import { createContext, useContext } from 'react';\nconst Theme = createContext('clair');\nfunction Texte(){\n  const t = useContext(Theme);\n  return <p>Theme : {t}</p>;\n}\nfunction App(){\n  return <Theme.Provider value=\"sombre\"><Texte /></Theme.Provider>;\n}"),
    "usereducer": ("useReducer (etats complexes)",
                   "import { useReducer } from 'react';\nconst init = {count: 0};\nfunction red(state, action){\n  if(action.type==='inc') return {count: state.count+1};\n  return state;\n}\nfunction C(){\n  const [s, dispatch] = useReducer(red, init);\n  return <button onClick={()=>dispatch({type:'inc'})}>{s.count}</button>;\n}"),
    "fetch": ("Fetch API (donnees)",
              "import { useState, useEffect } from 'react';\nfunction Users(){\n  const [users, setUsers] = useState([]);\n  useEffect(()=>{\n    fetch('https://jsonplaceholder.typicode.com/users')\n      .then(r=>r.json()).then(setUsers);\n  }, []);\n  return <ul>{users.map(u=><li key={u.id}>{u.name}</li>)}</ul>;\n}"),
    "chargement": ("Etat chargement/erreur",
                   "import { useState, useEffect } from 'react';\nfunction Data(){\n  const [etat, setEtat] = useState('chargement');\n  useEffect(()=>{\n    fetch('/api').then(()=>setEtat('ok')).catch(()=>setEtat('erreur'));\n  }, []);\n  if(etat==='chargement') return <p>Chargement...</p>;\n  if(etat==='erreur') return <p>Erreur !</p>;\n  return <p>OK</p>;\n}"),
    "lifting": ("Lifting state up",
                "import { useState } from 'react';\nfunction App(){\n  const [v, setV] = useState('');\n  return (<div><Champ v={v} setV={setV} /><Apercu v={v} /></div>);\n}\nfunction Champ({v, setV}){\n  return <input value={v} onChange={e=>setV(e.target.value)} />;\n}\nfunction Apercu({v}){\n  return <p>{v}</p>;\n}"),
    "lire_fichier": ("Lire un fichier (input file)",
                     "function LireFichier(){\n  const lire = (e)=>{\n    const f = e.target.files[0];\n    const r = new FileReader();\n    r.onload = ()=>alert(r.result.slice(0,200));\n    r.readAsText(f);\n  };\n  return <input type=\"file\" onChange={lire} />;\n}"),
    "modifier": ("Modifier un composant (setState)",
                 "import { useState } from 'react';\nfunction Editable(){\n  const [texte, setTexte] = useState('Bonjour');\n  return (<div><p>{texte}</p><button onClick={()=>setTexte('Modifie !')}>Modifier</button></div>);\n}"),
    "router": ("Navigation (react-router)",
               "import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';\nfunction App(){\n  return (<BrowserRouter><nav><Link to=\"/\">Accueil</Link></nav>\n  <Routes><Route path=\"/\" element={<h1>Accueil</h1>} /></Routes></BrowserRouter>);\n}"),
}
